  redirectText,
  startTurn,
} from './logic'
import { DECIDE_FILE, THRESHOLD_CHOICES, clampThreshold, runDecide, roleFor, type DecideIo } from './decide'

type Hooked = EngineInterface

const enabledA = atom({ plugin: 'session-panel', key: 'sessionPanelEnabled' } as const, true)
const askEnabledA = atom({ plugin: 'session-panel', key: 'askChoicesEnabled' } as const, false)
const askRuleA = atom({ plugin: 'session-panel', key: 'questionBoxRule' } as const, true)
const stopCheckA = atom({ plugin: 'session-panel', key: 'stopCheck' } as const, true)
const askedA = atom({ plugin: 'session-panel', key: 'askedThisTurn' } as const, false)
const settingsTabA = atom({ plugin: 'session-panel', key: 'settingsTab' } as const, 'band')
const settingsPageA = atom({ plugin: 'session-panel', key: 'settingsPage' } as const, 0)
const settingsOpenA = atom({ plugin: 'session-panel', key: 'settingsOpen' } as const, false)
const checklistA = atom({ plugin: 'session-panel', key: 'checklist' } as const, newChecklist())
const tickA = atom({ plugin: 'session-panel', key: 'tick' } as const, 0)
const styleA = atom({ plugin: 'session-panel', key: 'viewStyle' } as const, 'checklist' as CleanStyle)
const finishedA = atom({ plugin: 'session-panel', key: 'finished' } as const, [] as CleanFinished[])
const prefsA = atom({ plugin: 'session-panel', key: 'prefs' } as const, DEFAULT_PREFS as Prefs)
const enhancerA = atom({ plugin: 'session-panel', key: 'enhancer' } as const, { original: null, passText: null, notes: [], busy: false } as EnhancerState)
const gateDeniedA = atom({ plugin: 'session-panel', key: 'gateDenied' } as const, 0)
const trackA = atom({ plugin: 'session-panel', key: 'assumptionTrack' } as const, newTrack() as AssumptionTrack)
const versionA = atom({ plugin: 'session-panel', key: 'version' } as const, '')
/** The row whose full text is open, or null. One row at a time. */
const expandedA = atom({ plugin: 'session-panel', key: 'assumptionExpanded' } as const, null as number | null)
/** The rows printed while the reveal runs: a count, or null once it has finished (all rows print). */
const revealA = atom({ plugin: 'session-panel', key: 'assumptionReveal' } as const, null as number | null)
/** The columns the reader has hidden: ID, Turn, Text, Path or Time. Saved in the store as assumptionColumns. */
const hiddenColsA = atom({ plugin: 'session-panel', key: 'hiddenColumns' } as const, [] as string[])
/** The text of the last prompt the person sent. The prompt box is already empty by the time prompt.compose runs, so the
 * decision step reads the wording of the turn from here, not from the box. */
const submittedA = atom({ plugin: 'session-panel', key: 'submittedText' } as const, '')

const PLAN = 'mcp__session-panel__plan_steps'
const REPORT = 'mcp__session-panel__report_progress'
const ASK = 'mcp__session-panel__ask_choices'

let timer: Timer | undefined
let doneTimer: Timer | undefined
let lastInputAt = 0

function patch($: Hooked, fn: (c: CleanChecklist) => CleanChecklist) {
  return update($, checklistA, fn)
}

function runClock($: Hooked) {
  if (timer) return
  timer = $.clock.every(250, () => {
    void tickOnce($)
  })
}

async function tickOnce($: Hooked) {
  const c = await read($, checklistA)
  if (c.phase !== 'working' && c.phase !== 'needs-you') return
  await update($, tickA, n => (n ?? 0) + 1)
  await patch($, easeStep)
}

function stopClock() {
  timer?.cancel()
  timer = undefined
}

async function bell($: Hooked) {
  const now = await $.clock.now()
  // No focus API: ring only when the person has been quiet for a while.
  if (now - lastInputAt < 15000) return
  const isWindows = (await $.env.get('OS')) === 'Windows_NT'
  const argv = isWindows
    ? ['powershell', '-NoProfile', '-Command', '[console]::Beep(880,200)']
    : ['afplay', '/System/Library/Sounds/Ping.aiff']
  $.process.run(argv, { timeoutMs: 5000 }).catch(() => undefined)
}

async function needsYou($: Hooked, reason: string, question: CleanChecklist['question'] = null) {
  const before = await read($, checklistA)
  const isNew = before.phase !== 'needs-you' || before.isBelled === false
  await patch($, c => ({
    ...c,
    phase: 'needs-you',
    needsYouReason: reason,
    question,
    isBelled: true,
    finishedAt: 0,
  }))
  runClock($)
  if (isNew) await bell($)
}

function resume($: Hooked) {
  return patch($, c =>
    c.phase === 'needs-you' || c.phase === 'stuck'
      ? { ...c, phase: 'working', needsYouReason: '', stuckReason: '', question: null, isBelled: false }
      : c,
  )
}

/** Keeps the /config row in step with a button or slash command; a session without the row ignores the call. */
async function syncRow($: Hooked, field: string, value: string) {
  await $.config.set({ key: `session-panel.${field}`, value }).catch(() => undefined)
}

async function setStyle($: Hooked, value: CleanStyle) {
  await update($, styleA, () => value)
  await $.store.set('sessionPanelStyle', value)
  $.ui.toast(value === 'bars' ? 'Bar view' : 'List view')
  await syncRow($, 'view', value === 'bars' ? 'bars' : 'list')
}

async function setEnabled($: Hooked, value: boolean) {
  await update($, enabledA, () => value)
  await $.store.set('sessionPanelEnabled', value)
  $.ui.toast(value ? 'Session Panel is on: details are hidden.' : 'Session Panel is off: details are showing.')
  await syncRow($, 'sessionPanel', value ? 'on' : 'off')
}

async function setAskEnabled($: Hooked, value: boolean) {
  await update($, askEnabledA, () => value)
  await $.store.set('askChoicesEnabled', value)
  $.ui.toast(value ? 'ask_choices is on.' : 'ask_choices is off: Claude uses AskUserQuestion.')
  await syncRow($, 'askChoices', value ? 'on' : 'off')
}

// One-time copy of the choices the old clean-view plugin saved in its settings row, into this plugin's store.
// Only keys with no value yet are copied, and the flag keeps it from running twice.
async function migrateFromCleanView($: Hooked) {
  if ((await $.store.get('sessionPanelMigrated')) === true) return
  const user = (await $.settings.read({ source: 'user' }).catch(() => ({}))) as {
    pluginConfigs?: Record<string, { options?: Record<string, unknown> }>
  }
  const stored = {
    sessionPanelEnabled: await $.store.get('sessionPanelEnabled'),
    sessionPanelStyle: await $.store.get('sessionPanelStyle'),
    askChoicesEnabled: await $.store.get('askChoicesEnabled'),
  }
  for (const [key, value] of Object.entries(migratedValues(user.pluginConfigs, stored))) await $.store.set(key, value)
  await $.store.set('sessionPanelMigrated', true)
}

async function setPrefs($: Hooked, patch: Partial<Prefs>) {
  const next = { ...(await read($, prefsA)), ...patch }
  await update($, prefsA, () => next)
  await $.store.set('prefs', next)
}

async function setEnhancer($: Hooked, patch: Partial<EnhancerState>) {
  await update($, enhancerA, s => ({ ...s, ...patch }))
}

const NO_DRAFT: Partial<EnhancerState> = { original: null, passText: null, notes: [] }

/** Reads the box, enhances it and fills the box with the result. Returns the line to show the person. */
/** The text `/enhance <draft>` shows: the enhanced prompt, the model that answered, and the notes. */
function formatOutcome(r: Outcome): string {
  if (r.kind === 'off') return 'The enhancer is off. Open Settings to turn it on.'
  if (r.kind === 'empty') return 'Give a draft after /enhance, or type one in the box first.'
  if (r.kind === 'failed') return `Enhancer: ${r.reason}.`
  return [`Enhanced (via ${r.via}):`, r.prompt, '', ...r.notes.map(n => `· ${n}`)].join('\n')
}

/** The band's engine calls and state as plain functions. `$` cannot cross the import into enhancer.ts. */
function engineIo($: Hooked): EnhancerIo {
  return {
    home: async () => (await $.env.get('USERPROFILE')) ?? '',
    exists: p => $.fs.exists(p),
    read: p => $.fs.read(p),
    mtime: async p => (await $.fs.stat(p)).mtimeMs,
    list: p => $.fs.list(p),
    ancestors: async names => await $.fs.ancestors({ names }),
    cacheGet: async k => (await $.store.get(k)) as { mtimeMs: number; text: string } | undefined,
    cacheSet: (k, v) => $.store.set(k, v),
    gh: async args => {
      try {
        return await $.process.run(['gh', ...args])
      } catch {
        return undefined
      }
    },
    messages: async () => (await $.session.messages()).map(m => ({ role: m.role, text: m.text })),
    fork: async prompt => (await $.model.fork({ prompt })) as Awaited<ReturnType<EnhancerIo['fork']>>,
    complete: async (model, prompt) => (await $.model.complete({ model, prompt })) as Awaited<ReturnType<EnhancerIo['complete']>>,
    askUser: (question, options) => $.ui.ask(question, options),
  }
}

function deps($: Hooked): EnhancerDeps {
  return {
    ...engineIo($),
    prefs: () => read($, prefsA),
    state: () => read($, enhancerA),
    setState: patch => setEnhancer($, patch),
    readBox: async () => (await $.prompt.read()).text,
    fillBox: async text => void (await $.prompt.fill({ text, mode: 'replace' })),
    submitBox: async text => void (await $.prompt.submit({ text, asUser: true })),
    toast: text => $.ui.toast(text),
  }
}

/** First run: four questions, the answers saved. Runs once, or again from Settings. */
async function runSetup($: Hooked) {
  const on = (await $.ui.ask('Turn the enhancer on?', ['On (Recommended)', 'Off'])).startsWith('On')
  const modelAns = await $.ui.ask('Which model should the enhancer use?', ['Haiku (Recommended)', 'Sonnet', 'Opus'])
  const model = modelAns.startsWith('Sonnet') ? 'sonnet' : modelAns.startsWith('Opus') ? 'opus' : 'haiku'
  const view = (await $.ui.ask('Which band view by default?', ['List (Recommended)', 'Bars'])).startsWith('Bars') ? 'bars' : 'checklist'
  const srcAns = await $.ui.ask('Which context sources should the enhancer read?', ['All (Recommended)', 'Instructions and skills only', 'None'])
  const sources = srcAns.startsWith('All')
    ? { instructions: true, skills: true, docs: true, github: false }
    : srcAns.startsWith('Instructions')
      ? { instructions: true, skills: true, docs: false, github: false }
      : { instructions: false, skills: false, docs: false, github: false }
  const chat = (await $.ui.ask('How much chat should the enhancer read?', ['Haiku + recent (Recommended)', 'Full chat (session model)'])).startsWith('Full') ? 'full' : 'recent'
  await setPrefs($, { enhancerOn: on, model, chat, sources })
  await setStyle($, view)
  await $.store.set('setupDone', true)
}

/** Stop: cancels the running turn by the id turn.start gave us. Shown only while a turn runs. */
async function stopTurn($: Hooked) {
  const id = (await read($, trackA)).runningTurnId
  if (id === '') return
  await $.turn.abort({ turnId: id }).then(
    () => $.ui.toast('Stopped'),
    () => $.ui.toast('Nothing to stop: the turn has ended.'),
  )
}

/** Redirect: puts the start of a correction in the box. The person finishes it and sends; nothing is submitted here. */
async function redirectTo($: Hooked, entry: Assumption) {
  await $.prompt.fill({ text: redirectText(entry), mode: 'replace' })
}

/** Reads a file as text, or undefined when it is missing or cannot be read. */
async function readText($: Hooked, path: string): Promise<string | undefined> {
  try {
    const v = await $.fs.read(path)
    return typeof v === 'string' ? v : undefined
  } catch {
    return undefined
  }
}

/** /enhance-key and its Settings button, only when the person asks: Ctrl+X E for Enhance in keybindings.json. */
async function addEnhanceKey($: Hooked): Promise<string> {
  const none = () => undefined
  const dir = configDirOf({
    CLAUDE_CONFIG_DIR: await $.env.get('CLAUDE_CONFIG_DIR').catch(none),
    USERPROFILE: await $.env.get('USERPROFILE').catch(none),
    HOME: await $.env.get('HOME').catch(none),
  })
  if (dir === '') return 'No Claude config folder was found, so nothing was changed.'
  const path = `${dir}/keybindings.json`
  try {
    // a file that is there but cannot be read is never taken for a missing one
    const edit = enhanceKeyEdit((await $.fs.exists(path)) ? String(await $.fs.read(path)) : undefined)
    if (edit.write !== undefined) await $.fs.write(path, edit.write)
    return edit.line
  } catch (err) {
    return `keybindings.json could not be changed: ${String((err as any)?.message ?? err).slice(0, 160)}`
  }
}

/**
 * The sessions the registry lists (~/.claude/sessions/<pid>.json), read once. `complete` is false when a folder that is
 * there cannot be listed, or a record cannot be read: then no owner can be ruled out. A folder that is not there has no
 * sessions in it, so it is not a reason for `complete` to be false.
 */
async function readRegistry($: Hooked): Promise<{ live: Array<{ sessionId: string; name: string }>; complete: boolean }> {
  const none = () => undefined
  const home = (await $.env.get('USERPROFILE').catch(none)) || (await $.env.get('HOME').catch(none))
  const custom = await $.env.get('CLAUDE_CONFIG_DIR').catch(none)
  const dirs = [...new Set([custom, home ? `${homeOf({ USERPROFILE: home })}/.claude` : ''].filter((x): x is string => !!x).map(normPath))]
  const live: Array<{ sessionId: string; name: string }> = []
  let complete = true
  for (const dir of dirs) {
    const at = `${dir}/sessions`
    const there = await $.fs.exists(at).catch(() => undefined)
    if (there === undefined) {
      complete = false
      continue
    }
    if (!there) continue
    let listed: any[]
    try {
      listed = (await $.fs.list(at)) as any[]
      if (!listed || typeof listed.filter !== 'function') throw new Error('not a list')
    } catch {
      complete = false
      continue
    }
    for (const f of listed.filter(f => f.kind === 'file' && REGISTRY_RECORD.test(String(f.name)))) {
      try {
        const o = JSON.parse(String(await $.fs.read(`${at}/${f.name}`)))
        if (typeof o?.sessionId !== 'string') throw new Error('no session id')
        live.push({ sessionId: o.sessionId, name: typeof o.name === 'string' ? o.name : '' })
      } catch {
        // a record that cannot be read: the owner of a file may be in it, so the registry is not complete
        complete = false
      }
    }
  }
  return { live, complete }
}

/**
 * The registry, read again once after 200 ms when the first read was not whole: a record caught mid-rewrite is then read
 * cleanly, instead of tagging the session for its whole life.
 */
async function liveSessions($: Hooked): Promise<{ live: Array<{ sessionId: string; name: string }>; complete: boolean }> {
  const first = await readRegistry($)
  if (first.complete) return first
  await $.clock.sleep(200)
  return readRegistry($)
}

/** The OS as team-orchestrator reads it: the OS variable, then uname -s. Read once per load; it cannot change. */
let osKnown: Os | undefined
async function osOf($: Hooked): Promise<Os> {
  if (osKnown !== undefined) return osKnown
  const none = () => undefined
  const osVar = await $.env.get('OS').catch(none)
  if (osVar === 'Windows_NT') return (osKnown = 'windows')
  const r = await Promise.resolve().then(() => $.process.run(['uname', '-s'], { timeoutMs: 10000 })).catch(none)
  osKnown = osFrom(osVar, String(r?.stdout ?? ''))
  return osKnown
}

/**
 * Finds this session's file and loads what it holds. The name (from the registry) decides the file name; a file that
 * belongs to a closed session is taken over with its entries. Runs the first time a file is needed, so every path
 * that writes has the entries already. A track from an older load, or from a session that has since changed its id
 * (after /clear), is located again; a track already located for this session and file is returned as it is.
 */
async function locate($: Hooked, t: AssumptionTrack): Promise<AssumptionTrack> {
  const sessionId = await $.session.id()
  // a track already located for this session is kept without a registry read; a new id, an older track or a first call reads it.
  // A /rename is picked up at the next /clear or restart.
  if (t.file !== '' && t.sessionId === sessionId && !!t.member) return t
  const root = normPath(await $.session.root())
  const os = await osOf($)
  const { live, complete } = await liveSessions($)
  const name = live.find(s => s.sessionId.toLowerCase() === sessionId.toLowerCase() && s.name.trim() !== '')?.name
  const probe = name !== undefined ? `${assumptionsDir(root)}/${nameFile(name)}.json` : plainPath(root, sessionId)
  const baseText = await readText($, probe)
  const r = chooseFile({ root, sessionId, name, os, baseText, live, complete })
  if (t.file === r.file && t.sessionId === sessionId && t.member === (name ?? sessionId)) return t
  // a track located for another session id (before /clear) starts with no running turn; its entries come from the file
  if (t.sessionId !== '' && t.sessionId !== sessionId) t = { ...t, runningTurnId: '', turnDeclared: false, turnEdits: [], turnNo: 0, seq: 0 }
  const text = r.file === probe ? baseText : await readText($, r.file)
  const stored = parseStored(text)
  if (!stored.ok) {
    // a file this code cannot read is never written over: the list is shown empty and nothing is saved
    if (!t.warned) $.ui.toast(`Assumptions not loaded: ${stored.reason}. This session will not write its file.`)
    return { ...t, file: '', sessionId, member: name ?? sessionId, root, os, warned: true }
  }
  let loaded = loadTrack({ ...t, file: r.file, sessionId, member: name ?? sessionId, warned: t.warned || r.tagged, root, os, merged: stored.merged, idMap: stored.idMap }, stored.entries)
  // this session's own old id file (<session id>.json) is merged into the named file, once; another session's is never read
  const oldName = `${safeName(sessionId)}.json`
  const oldPath = plainPath(root, sessionId)
  let merged = false
  let old: ReturnType<typeof parseStored> | undefined
  let oldText: string | undefined
  if (name !== undefined && !r.tagged && oldPath !== r.file) {
    oldText = await readText($, oldPath)
    old = oldText === undefined ? undefined : parseStored(oldText)
    if (old?.ok && ownerOf(oldText as string) === sessionId && !loaded.merged.includes(oldName)) {
      loaded = mergeOld(loaded, { fileName: oldName, sessionId, entries: old.entries })
      merged = true
    }
  }
  // a takeover, or a merge, is written at once: the file's owner is this session, and the merge is recorded
  let saved = true
  if (r.takeover || merged) saved = await saveTrack($, loaded).then(wrote => wrote, () => false)
  // the old id file is retired only once the named file on disk holds its entries, so no assumption is counted twice.
  // A file merged on an earlier load is retired here if its retire write failed then.
  const holds = !merged || saved
  if (holds && old?.ok && ownerOf(oldText as string) === sessionId && old.entries.length > 0 && loaded.merged.includes(oldName)) {
    await $.fs.write(oldPath, retiredJson(sessionId, sessionId, r.file.split('/').pop() as string)).catch(() => undefined)
  }
  if (r.tagged && !t.warned) {
    $.ui.toast(`Assumptions: this session writes ${r.file.split('/').pop()}, because the usual file belongs to another session.`)
  }
  return loaded
}

/** Writes the list to this session's file, and takes the file over when its owner has closed. A file this code cannot read is left alone. */
async function saveTrack($: Hooked, t: AssumptionTrack): Promise<boolean> {
  if (t.file === '') return false
  if (!parseStored(await readText($, t.file)).ok) return false
  const ignore = t.file.replace(/\/assumptions\/[^/]+$/, '/.gitignore')
  if (!(await $.fs.exists(ignore))) await $.fs.write(ignore, STORE_IGNORE)
  await $.fs.write(t.file, storedJson(t.member, t.sessionId, t.entries, t.merged, t.idMap))
  return true
}

/** Changes the track. The file is found first, so new entries carry this session's id. When the list changed, the file is written at once. */
async function changeTrack($: Hooked, fn: (t: AssumptionTrack) => AssumptionTrack) {
  const current = await read($, trackA)
  // a session that cannot say where its file is still keeps its list on screen; it writes no file
  const before = await locate($, current).catch(() => current)
  let after = fn(before)
  if (after.entries !== before.entries) {
    try {
      await saveTrack($, after)
    } catch (err) {
      // the list still changes on screen; a failed file write must never break the turn that caused it
      $.ui.toast(`Assumptions file not written: ${String((err as any)?.message ?? err).slice(0, 80)}`)
    }
  }
  await update($, trackA, () => after)
  // a row whose entry is gone closes, so a later entry with the same id does not open expanded
  const expanded = await read($, expandedA)
  const kept = expandedAfterChange(expanded, after.entries)
  if (kept !== expanded) await update($, expandedA, () => kept)
  // content that appears while the section is open is revealed once; ordinary changes do not reveal again
  if (before.entries.length === 0 && after.entries.length > 0 && after.open) await startReveal($, after.entries.length)
}

/** At session start: find this session's file, read it back, and show what it holds. */
async function loadAssumptions($: Hooked) {
  const t = await locate($, await read($, trackA))
  await update($, trackA, () => t)
  const now = await $.clock.now()
  await changeTrack($, t => tidy(t, now))
}

/** The team heads for this session, read from the roster (read only). Undefined when it cannot be read or this session is not on it. */
async function headsOfRoster($: Hooked): Promise<Set<string> | undefined> {
  const root = (await $.session.root()).replace(/\\/g, '/')
  const text = await readText($, `${root}/.claude/team-orchestrator/roster.json`)
  return text === undefined ? undefined : headsFor(text, await $.session.id())
}

// The decision step (#91, slice 1). It never blocks a turn: the flag keeps its toast to one per load.
let decideWarned = false

/** The decision step's engine calls and state as plain functions, so the step can be tested without the band. */
function decideIo($: Hooked): DecideIo {
  return {
    rules: async () => {
      const root = (await $.session.root()).replace(/\\/g, '/')
      return readText($, `${root}/${DECIDE_FILE}`)
    },
    role: async () => {
      const root = (await $.session.root()).replace(/\\/g, '/')
      const text = await readText($, `${root}/.claude/team-orchestrator/roster.json`)
      return text === undefined ? undefined : roleFor(text, await $.session.id())
    },
    // the box is empty by the time prompt.compose runs, so the turn's wording comes from the last submitted prompt
    box: async () => read($, submittedA),
    paths: async () => (await read($, trackA)).turnEdits,
    entries: async () => (await locate($, await read($, trackA)).catch(() => read($, trackA))).entries,
    prefs: async () => {
      const p = await read($, prefsA)
      return { decide: p.decide, decideThreshold: p.decideThreshold, jev: p.jev }
    },
    now: () => $.clock.now(),
    toast: text => $.ui.toast(text),
    // the key is read from the environment, never stored, and never logged
    key: () => $.env.get('TYPESAFE_API_KEY').catch(() => undefined),
    // the one HTTP call: through $.http.fetch, as #91 requires, with the engine's own cancel-on-timeout
    fetch: args =>
      $.http.fetch({ url: args.url, method: args.method, headers: args.headers, body: args.body, timeoutMs: args.timeoutMs }).then(r => ({
        status: r.status,
        body: typeof r.body === 'string' ? r.body : '',
      })),
  }
}

/** Applies the status lines in a prompt. Returns the drop for a message that is only status lines, or null to let it go on. */
async function applyStatusLines($: Hooked, text: string): Promise<{ drop: string } | null> {
  const parts = sortPrompt(text)
  if (parts.refusal !== undefined) {
    // a prompt that is not exactly one envelope applies no status; it is dropped only if it carries status lines
    $.ui.toast(parts.refusal)
    return parts.statuses.length > 0 ? { drop: parts.refusal } : null
  }
  if (parts.statuses.length === 0) return null
  const heads = parts.statuses.some(s => s.sender !== 'user') ? await headsOfRoster($) : undefined
  const items = parts.statuses.map(s => {
    const cmd = parseIncoming(s.line)!
    const allowed = s.sender === 'user' || (heads?.has(s.sender) ?? false)
    const refusal =
      heads === undefined ? `Refused: the team roster cannot be read, so ${s.sender} cannot be checked.` : `Refused: ${s.sender} is not this session's team head.`
    return { ...cmd, allowed, refusal }
  })
  const now = await $.clock.now()
  const before = await read($, trackA)
  const applied = applyStatuses(before, items, now)
  if (applied.changed) await changeTrack($, () => applied.track)
  // a head's wrong does what the local Wrong button does: the box gets the Redirect text, and nothing is submitted
  for (const it of items) {
    const rid = it.id
    const was = before.entries.find(e => e.id === rid)
    const now2 = applied.track.entries.find(e => e.id === rid)
    if (it.allowed && it.verb === 'wrong' && was?.status === 'open' && now2?.status === 'wrong') await redirectTo($, now2)
  }
  const note = applied.notes.join(' ')
  $.ui.toast(note)
  return parts.other === '' ? { drop: note } : null
}

/** Confirm or Wrong on one entry: records the status and writes the file. */
async function resolveEntry($: Hooked, id: number, status: 'confirmed' | 'wrong') {
  const now = await $.clock.now()
  await changeTrack($, t => setStatus(t, id, status, now))
}

/** Wrong: records it, then puts the correction prefix in the box for the person to finish. */
async function wrongEntry($: Hooked, entry: Assumption) {
  await resolveEntry($, entry.id, 'wrong')
  await redirectTo($, entry)
}

/** Delete: an open entry is asked about first; a resolved one goes at once. There is no undo. */
async function deleteEntry($: Hooked, entry: Assumption) {
  if (entry.status === 'open') {
    // no picker in this session, or a Keep, leaves the entry where it is
    const answer = await $.ui.ask(deleteQuestion(entry), DELETE_OPTIONS).catch(() => 'Keep')
    if (answer !== 'Delete') return
  }
  await changeTrack($, t => removeEntry(t, entry.id))
}

/** Shows or hides one column of the table, and keeps the choice in the store. */
async function toggleColumn($: Hooked, key: string) {
  const current = await read($, hiddenColsA)
  if (!canHide(current, key)) {
    $.ui.toast(KEEP_ONE_MESSAGE)
    return
  }
  const next = toggled(current, key)
  await update($, hiddenColsA, () => next)
  await $.store.set('assumptionColumns', next)
}

/** Opens the full text of one row, or closes it when it is the open row. */
async function selectRow($: Hooked, id: number) {
  await update($, expandedA, cur => selectedAfter(cur, id))
}

/** Opens or closes the Assumptions section. Opening a section with entries runs the reveal. */
async function toggleSection($: Hooked) {
  const before = await read($, trackA)
  await update($, trackA, t => ({ ...t, open: !t.open }))
  if (!before.open && before.entries.length > 0) await startReveal($, before.entries.length)
}

/** Prints the rows one by one over about 400 ms: the frame is already there, then each row. Only the reveal's own timers change it. */
async function startReveal($: Hooked, count: number) {
  await update($, revealA, () => 0)
  const step = Math.max(1, Math.floor(400 / count))
  for (let i = 1; i <= count; i++) {
    $.clock.after(i * step, () => void update($, revealA, () => (i === count ? null : i)))
  }
}

/** Clear resolved: removes every confirmed and wrong entry, and says how many. */
async function clearResolved($: Hooked) {
  let count = 0
  await changeTrack($, t => {
    const dropped = dropResolved(t)
    count = dropped.count
    return dropped.track
  })
  $.ui.toast(`Cleared ${count} resolved assumptions.`)
}

/** Records the files a tool call wrote, for the Assumptions panel. A denied or failed call wrote nothing. */
async function recordEdits($: Hooked, e: { tool: unknown }, res: { deny?: unknown; isError?: boolean } | undefined) {
  const prefs = await read($, prefsA)
  if (!prefs.assumptions || !prefs.flagUndeclared || res?.deny !== undefined || res?.isError) return
  // a call that edits no file is left alone, so an ordinary tool call reads no registry
  const targets = editTargets(String(e.tool), e as unknown as Record<string, unknown>)
  if (targets.length === 0) return
  // only edits inside the project root count; the rest (a temp file, say) is ignored. Paths are kept relative to the root.
  const t = await locate($, await read($, trackA)).catch(() => undefined)
  if (t === undefined || t.root === '') return
  const inside = targets.map(p => relativeTo(t.root, p, t.os)).filter((p): p is string => p !== undefined)
  await update($, trackA, () => addEdits(t, inside))
}

/** A turn ended: an edit in a turn that stated no assumption becomes a flagged entry, when flagging is on. */
async function finishAssumptions($: Hooked, e: { agentId?: string }) {
  if (e.agentId !== undefined) return
  const prefs = await read($, prefsA)
  const flag = (await read($, enabledA)) && prefs.assumptions && prefs.flagUndeclared
  const now = await $.clock.now()
  await changeTrack($, t => tidy(finishTurn(t, flag, now), now))
}

function title0(cl: CleanChecklist): string {
  return cl.title === '' ? 'Working on it' : cl.title
}

export function registerSessionPanel(on: On, options: Record<string, unknown> = {}) {
  // ---------- session start: tools, command, saved setting ----------
  // The /config menu rows (options) win; where a row is unset, the setting kept by a button or command applies.
  on('session.start', async ($, e, next) => {
    await migrateFromCleanView($)
    // the version, read once per load from this plugin's own manifest, as team-orchestrator does
    const manifest = await readText($, `${$.plugin.root}/.claude-plugin/plugin.json`)
    await update($, versionA, () => versionFrom(manifest))
    await loadAssumptions($)
    // the column choice saved last time; a reload starts from what the reader left
    const stored = await $.store.get('assumptionColumns')
    const hidden = hiddenFrom(stored)
    await update($, hiddenColsA, () => hidden)
    // a stored state that hid both ID and Text is written back with ID shown
    if (Array.isArray(stored) && JSON.stringify(stored) !== JSON.stringify(hidden)) await $.store.set('assumptionColumns', hidden)
    const storedPrefs = (await $.store.get('prefs')) as Partial<Prefs> | undefined
    if (storedPrefs) await update($, prefsA, p => ({ ...p, ...storedPrefs, sources: { ...p.sources, ...storedPrefs.sources } }))
    const hasSetup = (await $.store.get('setupDone')) === true || (await $.store.get('sessionPanelEnabled')) !== undefined
    if (e.isInteractive && !hasSetup) {
      try {
        await runSetup($)
      } catch {
        // the questions could not be asked; the defaults stay and setup runs again next session
      }
    }
    const saved = options.sessionPanel === 'on' ? true : options.sessionPanel === 'off' ? false : await $.store.get('sessionPanelEnabled')
    if (typeof saved === 'boolean') await update($, enabledA, () => saved)
    const savedStyle = options.view === 'bars' ? 'bars' : options.view === 'list' ? 'checklist' : await $.store.get('sessionPanelStyle')
    if (savedStyle === 'bars' || savedStyle === 'checklist') await update($, styleA, () => savedStyle)
    const savedAsk = options.askChoices === 'on' ? true : options.askChoices === 'off' ? false : await $.store.get('askChoicesEnabled')
    if (typeof savedAsk === 'boolean') await update($, askEnabledA, () => savedAsk)
    await $.tool.register({
      name: 'plan_steps',
      description:
        'Session Panel: list the steps of the job in order, 1 to 8 short plain-English names starting with a verb (no paths, file names, commands or code). The first step starts at once. Call this first for every request.',
      inputSchema: {
        type: 'object',
        properties: { steps: { type: 'array', items: { type: 'string' }, minItems: 1, maxItems: 8 } },
        required: ['steps'],
      },
    })
    await $.tool.register({
      name: 'report_progress',
      description:
        'Session Panel: report progress on a planned step by its name and a percent from 0 to 100. Use 100 the moment the step is finished.',
      inputSchema: {
        type: 'object',
        properties: { task: { type: 'string' }, percent: { type: 'number' } },
        required: ['task', 'percent'],
      },
    })
    await $.tool.register({
      name: 'ask_choices',
      description:
        'Off by default: use AskUserQuestion to ask the person. Call this only if the person has said they turned on ask_choices. When on: ask a question with 2 to 4 options, the recommended option first, then stop and wait for their reply.',
      inputSchema: {
        type: 'object',
        properties: {
          question: { type: 'string' },
          options: { type: 'array', items: { type: 'string' }, minItems: 2, maxItems: 4 },
        },
        required: ['question', 'options'],
      },
    })
    await $.command.register({
      name: 'askchoices',
      description: 'Turn the ask_choices question tool on or off (no argument flips it). Off by default.',
      argumentHint: 'on|off',
    })
    await $.command.register({
      name: 'simple',
      description: 'Turn Session Panel on or off (no argument flips it), or pick the look: bars or list.',
      argumentHint: 'on|off|bars|list',
    })
    await $.command.register({ name: 'progress', description: 'Flip between the bar view and the list view.' })
    await $.command.register({ name: 'progress-clear', description: 'Remove the finished bars.' })
    await $.command.register({ name: 'enhance', description: 'Rewrite the prompt box, or /enhance <draft> to rewrite a draft given here.', argumentHint: '[draft]' })
    await $.command.register({ name: 'enhance-key', description: 'Add Ctrl+X E for Enhance to your keybindings.json.' })
    const c = await read($, checklistA)
    if (c.phase === 'working' || c.phase === 'needs-you') runClock($)
    return next(e)
  })

  // ---------- /simple ----------
  on('command.run', { command: 'simple' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'bars' || arg === 'list') {
      await setStyle($, arg === 'bars' ? 'bars' : 'checklist')
      return { text: arg === 'bars' ? 'Bar view.' : 'List view.' }
    }
    const current = await read($, enabledA)
    const value = arg === 'on' ? true : arg === 'off' ? false : !current
    await setEnabled($, value)
    return { text: value ? 'Session Panel is on.' : 'Session Panel is off.' }
  })

  on('command.run', { command: 'askchoices' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    const current = await read($, askEnabledA)
    const value = arg === 'on' ? true : arg === 'off' ? false : !current
    await setAskEnabled($, value)
    return { text: value ? 'ask_choices is on.' : 'ask_choices is off.' }
  })

  on('command.run', { command: 'progress' }, async ($) => {
    const now = await read($, styleA)
    await setStyle($, now === 'bars' ? 'checklist' : 'bars')
    return { text: now === 'bars' ? 'List view.' : 'Bar view.' }
  })
  on('command.run', { command: 'enhance' }, async ($, e) => {
    const draft = e.args.trim()
    if (draft === '') return { text: await runEnhance(deps($)) }
    // typed in the box: the result goes back in the box, as the Enhance button does, for a draft too long for the band
    if (e.origin.kind === 'composer') return { text: await runEnhance(deps($), draft) }
    try {
      return { text: formatOutcome(await enhance(engineIo($), draft, await read($, prefsA))) }
    } catch (err) {
      return { text: `Enhancer: ${String((err as any)?.message ?? err).slice(0, 160)}` }
    }
  })
  on('command.run', { command: 'enhance-key' }, async ($) => ({ text: await addEnhanceKey($) }))
  on('command.run', { command: 'progress-clear' }, async ($) => {
    await update($, finishedA, () => [])
    return { text: 'Finished bars removed.' }
  })

  // ---------- system prompt ----------
  on('prompt.compose', async ($, e, next) => {
    const result = await next(e)
    if (!(await read($, enabledA))) return result
    const text = rulesSection(await read($, askRuleA), await read($, askEnabledA))
    // The decision step (#91): one pointer digest of the assumptions worth reading this turn. Its own try keeps any
    // failure here from touching the sections below, and it never blocks the turn.
    let digest = ''
    try {
      const step = await runDecide(decideIo($), decideWarned)
      decideWarned = step.warned
      digest = step.text
    } catch {
      digest = ''
    }
    return {
      sections: [
        ...result.sections,
        { id: 'session-panel:plan', text: PLAN_SECTION, scope: 'session' as const },
        ...((await read($, prefsA)).assumptions ? [{ id: 'session-panel:assume', text: ASSUME_SECTION, scope: 'session' as const }] : []),
        ...(digest === '' ? [] : [{ id: 'session-panel:decide', text: digest, scope: 'session' as const }]),
        { id: 'session-panel:rules', text, scope: 'session' as const },
      ],
    }
  })

  // A grill skill's questions go through the question box. The note rides on the skill's own text, only when one loads,
  // so it costs no context on other turns.
  on('skill.prompt', async ($, e, next) => {
    const r = await next(e)
    if (!isGrillSkill(e.skill) || !(await read($, enabledA)) || !(await read($, askRuleA))) return r
    return { text: `${r.text}\n\n${GRILL_NOTE}` }
  })

  // ---------- a prompt starts a job ----------
  on('prompt.submit', async ($, e, next) => {
    // Status lines (typed by the user, or sent by the team head in an envelope) are applied here. A message that is only
    // status lines is dropped, so no model turn starts for it; any other text in it goes on to the model.
    const status = await applyStatusLines($, e.text)
    if (status !== null) return status
    await update($, submittedA, () => e.text)
    lastInputAt = await $.clock.now()
    const enh = await read($, enhancerA)
    const prefs = await read($, prefsA)
    if (enh.passText !== null && e.text === enh.passText) {
      await setEnhancer($, { passText: null })
      return next(e)
    }
    if (prefs.enhancerOn && prefs.autoEnhance && !e.text.startsWith('/') && e.text.trim() !== '') {
      const line = await runEnhance(deps($), e.text)
      return { drop: line }
    }
    if ((await read($, enabledA)) && (await read($, checklistA)).phase === 'needs-you') await resume($)
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    // subagents' and teammates' turns arrive here too; only the main loop's turn is this session's job
    if ((e as { agentId?: string }).agentId !== undefined) return next(e)
    await update($, trackA, t => startTurn(t, e.turnId))
    await update($, askedA, () => false)
    const result = await next(e)
    if (!(await read($, enabledA))) return result
    const text = e.text.trim()
    if (text === '' || text.startsWith('/')) return result
    const now = await $.clock.now()
    const before = await read($, checklistA)
    const isContinue = before.phase === 'needs-you' || before.phase === 'working'
    if (isContinue) {
      await resume($)
      runClock($)
      return result
    }
    doneTimer?.cancel()
    await patch($, c => startJob(c, now))
    const jobId = (await read($, checklistA)).jobId
    runClock($)
    void (async () => {
      const r = await $.model.complete({
        model: 'haiku',
        effort: 'low',
        maxTokens: 30,
        timeoutMs: 15000,
        prompt: `Name this job in 2 to 6 plain words, starting with a verb. Reply with the name only: no quotes, no file names, no punctuation.\n\nRequest: ${text.slice(0, 600)}`,
      })
      if (!r.isAnswered) return
      const title = cleanTitle(r.text)
      await patch($, c => (c.jobId === jobId ? { ...c, title } : c))
    })().catch(() => undefined)
    return result
  })

  // ---------- permission prompts ----------
  on('classic.Notification', async ($, e, next) => {
    if ((await read($, enabledA)) && /permission|elicitation/i.test(e.notification_type)) {
      await needsYou($, 'Claude needs your OK to continue')
    }
    return next(e)
  })

  // ---------- serve our tools ----------
  on('tool.call', { tool: 'mcp__session-panel__plan_steps' }, async ($, e) => {
    if (!(await read($, enabledA))) return { result: 'Session Panel is off. No plan needed. Continue the work.' }
    const steps = (e as { steps?: unknown }).steps
    // A subagent's plan is its own business: answer it, leave the member's checklist alone.
    if (e.agentId !== undefined) {
      const n = Array.isArray(steps) ? Math.min(Array.isArray(steps) ? steps.length : 0, 8) : 0
      return { result: n < 1 ? 'Give 1 to 8 short step names as an array of strings.' : `Planned ${n} steps. The first one has started.` }
    }
    const c = await read($, checklistA)
    const planned = planSteps(c, steps)
    if (planned === null) return { result: 'Give 1 to 8 short step names as an array of strings.' }
    await patch($, () => planned)
    runClock($)
    return { result: `Planned ${planned.tasks.length} steps. The first one has started.` }
  })

  on('tool.call', { tool: 'mcp__session-panel__report_progress' }, async ($, e) => {
    if (!(await read($, enabledA))) return { result: 'Session Panel is off. No progress report needed. Continue the work.' }
    const args = e as { task?: unknown; percent?: unknown }
    // A subagent's report never touches the member's checklist (the dock may read it per agent).
    if (e.agentId !== undefined) return { result: `Progress noted: ${clampPercent(args.percent)}%.` }
    let pct = 0
    await patch($, c => {
      const r = reportProgress(c, args.task, args.percent)
      pct = r.pct
      return r.cl.phase === 'stuck' ? { ...r.cl, phase: 'working', stuckReason: '', failStreak: 0 } : r.cl
    })
    runClock($)
    return { result: `Progress noted: ${pct}%.` }
  })

  on('tool.call', { tool: 'mcp__session-panel__ask_choices' }, async ($, e) => {
    if (!(await read($, enabledA)) || !(await read($, askEnabledA))) return { result: 'ask_choices is off. Ask this question with AskUserQuestion instead.' }
    if (await read($, askRuleA)) return { result: 'The question box is on: ask this with AskUserQuestion instead.' }
    const args = e as { question?: unknown; options?: unknown }
    // A helper cannot put a question on the person's screen: no Needs you, no bell, no picker.
    if (e.agentId !== undefined) {
      return { result: "Helpers can't ask the user. Put the question and its options in your final result so the agent that launched you can ask." }
    }
    const question = cleanName(typeof args.question === 'string' ? args.question.replace(/`[^`]*`/g, '') : '').replace(/…$/, '')
    const options = Array.isArray(args.options) ? args.options.filter((o): o is string => typeof o === 'string').slice(0, 4) : []
    if (options.length < 2) return { result: 'Give a question and 2 to 4 options.' }
    const q = typeof args.question === 'string' && args.question.trim() !== '' ? args.question.trim().slice(0, 160) : question
    await needsYou($, q, { question: q, options })
    return { result: 'The question is on the person’s screen. Stop now and wait for their reply.' }
  })

  on('tool.call', { tool: 'AskUserQuestion' }, async ($, e, next) => {
    await update($, askedA, () => true)
    return next(e)
  })

  // ---------- the gate and the bookkeeping for every other tool ----------
  on('tool.call', async ($, e, next) => {
    if (!(await read($, enabledA)) || e.agentId !== undefined) return next(e)
    const tool = String(e.tool)
    const c = await read($, checklistA)
    const isInJob = c.phase === 'working' || c.phase === 'needs-you' || c.phase === 'stuck'
    // The gate counts its denials. A plan, or the end of the job, resets the count. After GATE_LIMIT denials in a row the
    // tool goes through, so a session that cannot see plan_steps is never trapped.
    if (!isInJob || c.hasPlan) await update($, gateDeniedA, () => 0)
    if (isInJob && !c.hasPlan && !isGateExempt(tool)) {
      const denied = (await read($, gateDeniedA)) + 1
      await update($, gateDeniedA, () => denied)
      if (denied <= GATE_LIMIT) return { deny: GATE_MESSAGE }
      if (denied === GATE_LIMIT + 1) $.ui.toast('Session Panel: no plan_steps call after 3 tries, so tools are open.')
    }

    const isOurs = tool === PLAN || tool === REPORT || tool === ASK
    if (!isOurs) {
      await patch($, cl => ({
        ...cl,
        action: tool === 'ToolSearch' || tool === 'TodoWrite' || tool.startsWith('Task') ? cl.action : actionLabel(tool),
      }))
    }
    if (tool === 'AskUserQuestion') {
      const qs = (e as { questions?: Array<{ question?: string }> }).questions
      await needsYou($, qs?.[0]?.question ?? 'Claude has a question for you')
    }

    const res = await next(e)
    await recordEdits($, e, res)
    if (isOurs) return res

    const isFailure = res.deny === undefined && res.isError === true
    if (res.deny === undefined && !isFailure) {
      if (tool === 'Edit' || tool === 'Write' || tool === 'NotebookEdit') {
        const file = String((e as { file_path?: string; notebook_path?: string }).file_path ?? (e as { notebook_path?: string }).notebook_path ?? '')
        if (file !== '') await patch($, cl => (cl.changedFiles.includes(file) ? cl : { ...cl, changedFiles: [...cl.changedFiles, file] }))
      }
      if (tool === 'TodoWrite') await patch($, cl => applyTodos(cl, (e as { todos?: unknown }).todos))
      if (tool === 'TaskCreate') {
        const m = /#?(\d+)/.exec(res.text ?? '')
        await patch($, cl => applyTaskCreate(cl, (e as { subject?: unknown }).subject, m?.[1] ?? String(cl.tasks.length + 1)))
      }
      if (tool === 'TaskUpdate') await patch($, cl => applyTaskUpdate(cl, e as { taskId?: unknown; status?: unknown; subject?: unknown }))
    }
    await patch($, cl => {
      let out: CleanChecklist = cl
      if (tool === 'AskUserQuestion' || (cl.phase === 'needs-you' && cl.question === null)) {
        out = { ...out, phase: 'working', needsYouReason: '', isBelled: false }
      }
      if (res.deny !== undefined) return out
      if (!isFailure) {
        return out.phase === 'stuck' ? { ...out, phase: 'working', stuckReason: '', failStreak: 0 } : { ...out, failStreak: 0 }
      }
      if (looksLikeUserDenial(res.text ?? '')) {
        return { ...out, phase: 'stuck', stuckReason: 'you said no to a step, so Claude paused' }
      }
      const streak = out.failStreak + 1
      return streak >= 3
        ? { ...out, failStreak: streak, phase: 'stuck', stuckReason: 'a step keeps failing, Claude is trying another way' }
        : { ...out, failStreak: streak }
    })
    return res
  })

  // ---------- the end of a turn ----------
  // ---------- assumptions: what Claude states, and edits that state none ----------
  on('session.append', { door: 'response' }, async ($, e, next) => {
    const isOn = (await read($, enabledA)) && (await read($, prefsA)).assumptions
    if (isOn && (e as { agentId?: string }).agentId === undefined) {
      const text = responseText((e.message as { content?: unknown } | undefined)?.content)
      const now = await $.clock.now()
      await changeTrack($, t => addDeclared(t, parseAssumptions(text), now))
    }
    return next(e)
  })


  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    await finishAssumptions($, e)
    const proseQuestion = e.agentId === undefined && e.reason !== 'aborted' && e.reason !== 'error' && e.reason !== 'refusal' && asksUser(e.answer)
    if (proseQuestion && (await read($, enabledA)) && (await read($, askRuleA)) && (await read($, stopCheckA)) && !(await read($, askedA))) {
      $.ui.toast('Claude asked in prose instead of the question box. Turn the warning off in Settings → Questions if it is not wanted.')
    }
    if (e.agentId !== undefined || !(await read($, enabledA))) return result
    const now = await $.clock.now()
    const c = await read($, checklistA)
    if (c.phase === 'idle') return result
    if (e.reason === 'aborted') {
      stopClock()
      await patch($, cl => ({ ...cl, phase: 'stopped', finishedAt: now, action: '', question: null }))
    } else if (e.reason === 'error') {
      stopClock()
      await patch($, cl => ({ ...cl, phase: 'stuck', stuckReason: friendlyError(e.answer), finishedAt: now, action: '' }))
    } else if (e.reason === 'refusal') {
      stopClock()
      await patch($, cl => ({ ...cl, phase: 'stuck', stuckReason: "Claude couldn't help with that request", finishedAt: now, action: '' }))
    } else if (c.question !== null) {
      await needsYou($, c.question.question, c.question)
    } else if (c.hasPlan && c.tasks.some(t => t.status !== 'done') && asksUser(e.answer)) {
      // Unfinished steps only mean "waiting for you" when Claude actually asked something; a final answer with no
      // question means the job is done, even if the last step was never reported at 100.
      await needsYou($, 'Claude is waiting for your reply')
    } else {
      stopClock()
      await patch($, cl => ({
        ...cl,
        phase: 'done',
        finishedAt: now,
        action: '',
        isCollapsed: false,
        tasks: cl.tasks.map(t => ({ ...t, status: 'done' as const, percent: 100, hasReported: true })),
      }))
      const seconds = Math.max(0, Math.round((now - c.startedAt) / 1000))
      await update($, finishedA, f => [...f, { id: `j${c.jobId}`, title: c.title === '' ? 'Working on it' : c.title, seconds, steps: c.tasks.map(t => t.name) }].slice(-3))
      doneTimer?.cancel()
      doneTimer = $.clock.after(5000, () => {
        void patch($, cl => (cl.phase === 'done' ? { ...cl, isCollapsed: true } : cl))
      })
    }
    return result
  })

  // ---------- hide the noise ----------
  on('ui.render', { component: 'ToolUse' }, async ($, e, next) => {
    if (!(await read($, enabledA))) return next(e)
    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })
  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => {
    if (!(await read($, enabledA))) return next(e)
    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })
  on('ui.render', { component: 'ToolGroup' }, async ($, e, next) => {
    if (!(await read($, enabledA))) return next(e)
    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })
  on('ui.render', { component: 'ToolProgress' }, async ($, e, next) => {
    if (!(await read($, enabledA))) return next(e)
    return next({ ...e, props: { ...e.props, hint: '' } })
  })

  // ---------- the band ----------
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    // Another mod's band (below us in the chain) stays on screen: it goes above ours, in a column.
    let rest: Awaited<ReturnType<typeof next>> | undefined
    try {
      rest = await next(e)
    } catch {
      rest = undefined
    }
    const stack = (own: RenderElement): RenderElement =>
      rest ? (
        <Box flexDirection="column">
          {rest}
          {own}
        </Box>
      ) : (
        own
      )
    try {
    const enabled = await read($, enabledA)
    const cl = await read($, checklistA)
    const tick = await read($, tickA)
    const now = await $.clock.now()
    const isPlain = ((await $.env.get('NO_COLOR')) ?? '') !== ''
    const isStill =
      ((await $.env.get('NO_MOTION')) ?? '') !== '' ||
      ((await $.env.get('REDUCE_MOTION')) ?? '') !== '' ||
      ((await $.env.get('PREFERS_REDUCED_MOTION')) ?? '') !== ''
    const color = (c: string): string | undefined => (isPlain ? undefined : c)
    // The whole mod sits in one rounded frame so it never blends into another mod's band. Inside it, `width` is the
    // room left after the two border cells and one cell of padding on each side.
    const outer = e.props.bodyColumns
    const width = Math.max(20, outer - 4)
    const files = cl.changedFiles.length
    const elapsed = formatDuration((cl.finishedAt > 0 ? cl.finishedAt : now) - cl.startedAt)
    const style = await read($, styleA)
    const finished = await read($, finishedA)
    const askOn = await read($, askEnabledA)
    const askRule = await read($, askRuleA)
    const stopCheck = await read($, stopCheckA)
    const settingsOpen = await read($, settingsOpenA)
    const settingsTab = await read($, settingsTabA)
    const settingsPage = await read($, settingsPageA)
    const prefs = await read($, prefsA)
    const enh = await read($, enhancerA)
    const version = await read($, versionA)
    const track = await read($, trackA)
    const hiddenCols = await read($, hiddenColsA)
    const reveal = await read($, revealA)
    const expanded = await read($, expandedA)

    // Coloured words that carry the state: a filled pill for what is on or chosen, plain dim words for the rest.
    const pillOf = (label: string, bg: string) => (
      <Text weight="bold" inverse={isPlain} backgroundColor={isPlain ? undefined : bg} color={isPlain ? undefined : 'white'}>
        {` ${label} `}
      </Text>
    )

    // Settings are data: add an entry here and it shows in the dropdown. A toggle is on or off; a choice picks one value.
    type Setting =
      | { id: string; group: string; label: string; hint: string; kind: 'toggle'; isOn: boolean; set: (v: boolean) => void }
      | { id: string; group: string; label: string; hint: string; kind: 'button'; press: () => void; action: string }
      | { id: string; group: string; label: string; hint: string; kind: 'choice'; value: string; options: Array<{ value: string; label: string }>; set: (v: string) => void }
    const settings: Setting[] = [
      {
        id: 'details',
        group: 'band',
        label: 'Hide tool details',
        hint: 'Show a step checklist instead of every tool call',
        kind: 'toggle',
        isOn: enabled,
        set: v => void setEnabled($, v),
      },
      {
        id: 'ask',
        group: 'questions',
        label: 'Picker above the prompt',
        hint: 'ask_choices buttons. Off while the question box is on.',
        kind: 'toggle',
        isOn: askOn,
        set: v => void setAskEnabled($, v),
      },
      {
        id: 'questionbox',
        group: 'questions',
        label: 'Question box',
        hint: 'Claude asks with AskUserQuestion, never in prose',
        kind: 'toggle',
        isOn: askRule,
        set: v => void update($, askRuleA, () => v),
      },
      {
        id: 'stopcheck',
        group: 'questions',
        label: 'Warn on prose questions',
        hint: 'A toast when a reply ends with a question not asked in the box',
        kind: 'toggle',
        isOn: stopCheck,
        set: v => void update($, stopCheckA, () => v),
      },
      {
        id: 'look',
        group: 'band',
        label: 'Progress look',
        hint: 'A checklist or one bar for each job',
        kind: 'choice',
        value: style === 'bars' ? 'bars' : 'list',
        options: [
          { value: 'list', label: 'List' },
          { value: 'bars', label: 'Bars' },
        ],
        set: v => void setStyle($, v === 'bars' ? 'bars' : 'checklist'),
      },
      {
        id: 'enhancer',
        group: 'enhancer',
        label: 'Enhancer',
        hint: 'Show Enhance, Undo and Send above the prompt',
        kind: 'toggle',
        isOn: prefs.enhancerOn,
        set: v => void setPrefs($, { enhancerOn: v }),
      },
      {
        id: 'auto',
        group: 'enhancer',
        label: 'Auto-enhance on Enter',
        hint: 'Enhance first and fill the box. Enter again sends.',
        kind: 'toggle',
        isOn: prefs.autoEnhance,
        set: v => void setPrefs($, { autoEnhance: v }),
      },
      {
        id: 'key',
        group: 'enhancer',
        label: 'Add Ctrl+X E for Enhance',
        hint: 'Adds the key to keybindings.json',
        kind: 'button',
        action: 'Add',
        press: () => void addEnhanceKey($).then(line => $.ui.toast(line)),
      },
      {
        id: 'assume',
        group: 'assumptions',
        label: 'Track assumptions',
        hint: 'Claude states each assumption; the band lists them',
        kind: 'toggle',
        isOn: prefs.assumptions,
        set: v => void setPrefs($, { assumptions: v }),
      },
      {
        id: 'flag',
        group: 'assumptions',
        label: 'Flag undeclared edits',
        hint: 'Note each edit in a turn that states no assumption',
        kind: 'toggle',
        isOn: prefs.flagUndeclared,
        set: v => void setPrefs($, { flagUndeclared: v }),
      },
      {
        id: 'decide',
        group: 'assumptions',
        label: 'Decision step',
        hint: 'Point the model at the assumptions worth reading this turn',
        kind: 'toggle',
        isOn: prefs.decide,
        set: v => void setPrefs($, { decide: v }),
      },
      {
        id: 'threshold',
        group: 'assumptions',
        label: 'Keep threshold',
        hint: 'Rules in .claude/session-panel/decide.json win over this',
        kind: 'choice',
        value: String(prefs.decideThreshold),
        options: THRESHOLD_CHOICES.map(n => ({ value: String(n), label: n.toFixed(1) })),
        set: v => void setPrefs($, { decideThreshold: clampThreshold(Number(v)) }),
      },
      {
        id: 'jev',
        group: 'assumptions',
        label: 'Jev pass',
        hint: 'A second opinion from TypeSafe, one request per turn. Needs TYPESAFE_API_KEY.',
        kind: 'toggle',
        isOn: prefs.jev,
        set: v => void setPrefs($, { jev: v }),
      },
      {
        id: 'model',
        group: 'enhancer',
        label: 'Model',
        hint: 'Used when the conversation has no reply to fork yet',
        kind: 'choice',
        value: prefs.model,
        options: [
          { value: 'haiku', label: 'Haiku' },
          { value: 'sonnet', label: 'Sonnet' },
          { value: 'opus', label: 'Opus' },
        ],
        set: v => void setPrefs($, { model: v }),
      },
      {
        id: 'chat',
        group: 'enhancer',
        label: 'Chat context',
        hint: 'Recent: Haiku reads the last six turns. Full chat: forks the session with its model.',
        kind: 'choice',
        value: prefs.chat,
        options: [
          { value: 'recent', label: 'Recent' },
          { value: 'full', label: 'Full chat' },
        ],
        set: v => void setPrefs($, { chat: v === 'full' ? 'full' : 'recent' }),
      },
      ...(['instructions', 'skills', 'docs', 'github'] as const).map(src => ({
        id: `src-${src}`,
        group: 'enhancer',
        label: SOURCE_SHORT[src].label,
        hint: SOURCE_SHORT[src].hint,
        kind: 'toggle' as const,
        isOn: prefs.sources[src],
        set: (v: boolean) => void setPrefs($, { sources: { ...prefs.sources, [src]: v } }),
      })),
      {
        id: 'again',
        group: 'setup',
        label: 'Run setup again',
        hint: 'Ask the first-run questions again',
        kind: 'button',
        action: 'Run',
        press: () => void runSetup($),
      },
    ]
    const GROUPS: Array<{ id: string; title: string; note?: string }> = [
      { id: 'band', title: 'Band' },
      { id: 'enhancer', title: 'Enhancer' },
      { id: 'questions', title: 'Questions' },
      { id: 'assumptions', title: 'Assumptions' },
      { id: 'shelf', title: 'Shelf', note: 'Coming in a later stage.' },
      { id: 'setup', title: 'Setup' },
    ]
    const activeGroup = GROUPS.find(g => g.id === settingsTab) ?? GROUPS[0]
    const tabSettings = settings.filter(s => s.group === activeGroup.id)
    // The card is a table with three fixed columns: selector | name | description. Every cell is a box of its column's
    // width that never shrinks, so each column starts at the same place on every row of the tab, on every page.
    const CARD_LINES = 6
    const CARD_HEIGHT = 2 + 1 + 2 + CARD_LINES
    const cardInner = width - 4
    const optionWidth = (label: string) => label.length + 2
    const selectorWidth = (s: Setting) =>
      s.kind === 'toggle'
        ? 5
        : s.kind === 'button'
          ? optionWidth(s.action)
          : s.options.reduce((n, o) => n + optionWidth(o.label), 0)
    const tcols = tableWidths(cardInner, tabSettings.map(selectorWidth), tabSettings.map(s => s.label))
    // On a narrow card the description goes on the lines under the name, in the same column, instead of beside it.
    const stacked = tcols.desc < 30
    const descW = stacked ? Math.max(MIN_DESC, cardInner - tcols.selector - TABLE_GAP) : tcols.desc
    const rowWidth = stacked ? tcols.selector + TABLE_GAP + Math.max(tcols.name, descW) : tcols.selector + tcols.name + tcols.desc + 2 * TABLE_GAP
    const linesOf = (s: Setting) => wrapWords(s.hint, descW)
    const heightOf = (s: Setting) => linesOf(s).length + (stacked ? 1 : 0)
    const selectorCell = (s: Setting): RenderChildren => {
      if (s.kind === 'toggle') return s.isOn ? pillOf('ON', 'green') : pillOf('OFF', 'gray')
      if (s.kind === 'button') return <Button key={`set-${s.id}`} plain label={`[${s.action}]`} onPress={s.press} />
      return s.options.map(o => (
        <Box key={`opt-${s.id}-${o.value}`} flexDirection="row" flexShrink={0}>
          {o.value === s.value ? (
            pillOf(o.label, 'magenta')
          ) : (
            <Box width={optionWidth(o.label)} flexShrink={0} paddingLeft={1}>
              <Button key={`set-${s.id}-${o.value}`} plain dimColor label={o.label} onPress={() => s.set(o.value)} />
            </Box>
          )}
        </Box>
      ))
    }
    const nameCell = (s: Setting): RenderChildren =>
      s.kind === 'toggle' ? <Button key={`set-${s.id}`} plain label={s.label} onPress={() => s.set(!s.isOn)} /> : <Text weight="bold">{s.label}</Text>
    const descCell = (s: Setting) => (
      <Box width={descW} flexShrink={0} flexDirection="column">
          {linesOf(s).map((line, i) => (
            <Text key={`d${i}`} dimColor>{line}</Text>
          ))}
      </Box>
    )
    const settingRow = (s: Setting) =>
      stacked ? (
        <Box key={`row-${s.id}`} flexDirection="column" width={rowWidth} flexShrink={0}>
          <Box flexDirection="row" flexShrink={0}>
        <Box width={tcols.selector} flexShrink={0} flexDirection="row">{selectorCell(s)}</Box>
        <Box width={TABLE_GAP} flexShrink={0} />
        <Box width={tcols.name} flexShrink={0} flexDirection="row">{nameCell(s)}</Box>
          </Box>
          <Box flexDirection="row" flexShrink={0}>
            <Box width={tcols.selector + TABLE_GAP} flexShrink={0} />
            {descCell(s)}
          </Box>
        </Box>
      ) : (
        <Box key={`row-${s.id}`} flexDirection="row" width={rowWidth} flexShrink={0}>
        <Box width={tcols.selector} flexShrink={0} flexDirection="row">{selectorCell(s)}</Box>
        <Box width={TABLE_GAP} flexShrink={0} />
        <Box width={tcols.name} flexShrink={0} flexDirection="row">{nameCell(s)}</Box>
          <Box width={TABLE_GAP} flexShrink={0} />
          {descCell(s)}
        </Box>
      )
    const tabText = (title: string) => ` ${title} `
    const tabsWidth = GROUPS.reduce((n, g) => n + tabText(g.title).length, 0)
    // Tabs: the open tab's label is a filled pill and its rule is blank, so it joins the body under it; the others sit on a rule.
    const tabRow = (
      <Box flexDirection="column">
        <Box flexDirection="row">
          {GROUPS.map(g =>
            g.id === activeGroup.id ? (
              <Box key={`tab-${g.id}`}>{pillOf(g.title, 'cyan')}</Box>
            ) : (
              <Button
                key={`tab-btn-${g.id}`}
                plain
                label={tabText(g.title)}
                onPress={() => {
                  void update($, settingsTabA, () => g.id)
                  void update($, settingsPageA, () => 0)
                }}
              />
            ),
          )}
        </Box>
        <Box flexDirection="row">
          {GROUPS.map(g => {
            const w = tabText(g.title).length
            return <Text key={`rule-${g.id}`} dimColor>{g.id === activeGroup.id ? ' '.repeat(w) : '─'.repeat(w)}</Text>
          })}
          <Text dimColor>{'─'.repeat(Math.max(0, cardInner - tabsWidth))}</Text>
        </Box>
      </Box>
    )
    // The body holds CARD_LINES lines. A tab with more is paged; Prev and Next sit on the title line, so they stay visible.
    const pages = pageRows(tabSettings, tabSettings.map(heightOf), CARD_LINES)
    const pageNo = Math.min(settingsPage, pages.length - 1)
    const pageControls = pages.length > 1 ? (
      <Box flexDirection="row">
        {pageNo > 0 ? <Button key="page-prev" plain label="◀ Prev" onPress={() => void update($, settingsPageA, () => pageNo - 1)} /> : <Text dimColor>{'       '}</Text>}
        <Text dimColor>{`  ${pageNo + 1} / ${pages.length}  `}</Text>
        {pageNo < pages.length - 1 ? <Button key="page-next" plain label="Next ▶" onPress={() => void update($, settingsPageA, () => pageNo + 1)} /> : null}
      </Box>
    ) : null
    const tabBody = (
      <Box flexDirection="column" height={CARD_LINES} flexShrink={0}>
        {activeGroup.note ? <Text dimColor>{activeGroup.note}</Text> : pages[pageNo].map(settingRow)}
      </Box>
    )

    // The panel is hidden when there are no assumptions. Otherwise: a title with the open count, and when open a table: a
    // header, a rule, then one line per entry with a light rule between entries. Each line is drawn as pieces, padded to the
    // column widths, so every header sits above its contents; the buttons sit in the last column, beside their row.
    const cols = tableColumns(width - 2, track.entries, hiddenCols)
    const actionsWidth = cols.find(c => c.key === 'actions')!.width
    const paint = (c: string | undefined) => (c === undefined ? undefined : color(c))
    // the bars and rules are dim; the status and cat cells take their colour; a resolved row dims its text, not its status
    // a stale open entry (three days or more) shows dim, with its status colour; the stored status is still open
    const nowMs = Date.now()
    // a row prints on one line; its ID and Text cells are buttons that open the row's full text below it
    const rowNodes = (a: Assumption) =>
      rowPieces(cols, a, nowMs).map((p, i) => {
        const key = `c${i}`
        if (p.key === 'bar') return <Text key={key} dimColor>{p.text}</Text>
        if (p.key === 'status') return <Text key={key} dimColor={isStale(a, nowMs)} color={paint(cellColor('status', a.status))}>{p.text}</Text>
        if (p.key === 'kind') return <Text key={key} color={paint(cellColor('kind', a.kind))}>{p.text}</Text>
        if (p.key === 'text') return <Button key={`text-${a.id}`} plain dimColor={a.status !== 'open'} label={p.text} onPress={() => void selectRow($, a.id)} />
        if (p.key === 'id') return <Button key={`id-${a.id}`} plain dimColor label={p.text} onPress={() => void selectRow($, a.id)} />
        return <Text key={key} dimColor>{p.text}</Text>
      })
    // The title is a heavy bar; open, it sits at the top of a single-line frame with the column toggles and the table.
    // While the reveal runs, only the first `reveal` rows print; afterwards (reveal null) all of them do.
    const titleRow = (
      <Box flexDirection="row">
        <Button key="assumptions-toggle" plain label={`==== ASSUMPTIONS (${openCount(track)} open) ====`} onPress={() => void toggleSection($)} />
        {track.entries.some(e => e.status !== 'open') ? (
          <Button key="clear-resolved" plain label="  ⌫ Clear resolved" onPress={() => void clearResolved($)} />
        ) : null}
      </Box>
    )
    const shownRows = reveal === null ? panelOrder(track.entries) : panelOrder(track.entries).slice(0, reveal)
    const assumptionsBlock = prefs.assumptions && track.entries.length > 0 ? (
      track.open ? (
        <Box key="assumptions-frame" flexDirection="column" borderStyle="single">
          {titleRow}
          <Box flexDirection="row">
            <Text dimColor>cols: </Text>
            {TOGGLES.map(t => (
              <Button key={`col-${t.key}`} plain label={`${t.label} ${hiddenCols.includes(t.key) ? '☐' : '☑'}  `} onPress={() => void toggleColumn($, t.key)} />
            ))}
          </Box>
          <Text dimColor>{'─'.repeat(width - 2)}</Text>
          <Box flexDirection="row">
            {headerPieces(cols).map((p, i) => (p.key === 'bar' ? <Text key={`h${i}`} dimColor>{p.text}</Text> : <Text key={`h${i}`} weight="bold">{p.text}</Text>))}
          </Box>
          <Box flexDirection="row">
            {rulePieces(cols).map((p, i) => <Text key={`r${i}`} dimColor>{p.text}</Text>)}
          </Box>
          {shownRows.map((a, i) => (
            <Box key={`row-${a.id}`} flexDirection="column">
              {i > 0 ? (
                <Box flexDirection="row">
                  {rulePieces(cols).map((p, j) => <Text key={`s${j}`} dimColor>{p.text}</Text>)}
                </Box>
              ) : null}
              <Box flexDirection="row">
                {rowNodes(a)}
                <Box width={actionsWidth} flexDirection="row">
                  {a.status === 'open' ? <Button key={`confirm-${a.id}`} plain label="✓ Confirm" onPress={() => void resolveEntry($, a.id, 'confirmed')} /> : null}
                  {a.status === 'open' ? <Text> </Text> : null}
                  {a.status === 'open' ? <Button key={`wrong-${a.id}`} plain label="✗ Wrong" onPress={() => void wrongEntry($, a)} /> : null}
                  {a.status === 'open' ? <Text> </Text> : null}
                  <Button key={`delete-${a.id}`} plain label="⌫ Delete" onPress={() => void deleteEntry($, a)} />
                </Box>
              </Box>
              {expanded === a.id ? (
                <Box key={`full-${a.id}`} flexDirection="column">
                  <Text wrap="wrap">{a.text}</Text>
                  {a.kind === 'flagged' ? <Text dimColor wrap="wrap">{`Path: ${(a.paths ?? [a.path ?? '']).join(', ')}`}</Text> : null}
                </Box>
              ) : null}
            </Box>
          ))}
        </Box>
      ) : (
        titleRow
      )
    ) : null
    const enhancerBar = (
      <Box flexDirection="column">
        <Box flexDirection="row">
          <Button key="enhance" variant="primary" label={enh.busy ? 'Enhancing…' : 'Enhance'} onPress={() => void runEnhance(deps($)).then(line => $.ui.toast(line))} />
          <Button key="undo" label="Undo" onPress={() => void undoEnhance(deps($))} />
          <Button key="send" label="Send" onPress={() => void sendBox(deps($))} />
          {track.runningTurnId !== '' ? <Button key="stop" label="Stop" onPress={() => void stopTurn($)} /> : null}
        </Box>
        {enh.notes.map((n, i) => (
          <Text key={`note-${i}`} dimColor wrap="truncate">{`· ${n}`}</Text>
        ))}
      </Box>
    )
    const settingsButton = (
      <Button
        key="settings"
        variant={settingsOpen ? 'primary' : 'secondary'}
        label={settingsOpen ? '⚙ Settings ▴' : '⚙ Settings ▾'}
        onPress={() => void update($, settingsOpenA, v => !v)}
      />
    )
    // Frame: a title tab and the Settings button on top, the dropdown under them, then the body.
    const frame = (body: RenderChildren): RenderElement =>
      stack(
        <Box flexDirection="column" borderStyle="round" borderColor={color('cyan')} paddingX={1} width={outer} minHeight={settingsOpen ? CARD_HEIGHT + 3 : undefined}>
          <Box flexDirection="row" justifyContent="space-between" width={width}>
            <Box flexDirection="row">
              <Text weight="bold" inverse={isPlain} backgroundColor={isPlain ? undefined : 'cyan'} color={isPlain ? undefined : 'black'}>
                {enabled ? ' Session Panel ' : ' Session Panel · off '}
              </Text>
              {version !== '' ? <Text dimColor>{` v${version}`}</Text> : null}
            </Box>
            {settingsButton}
          </Box>
          {enhancerBar}
          {assumptionsBlock}
          {body}
          {settingsOpen ? (
            <Box position="absolute" top={1} right={0} flexDirection="column">
              <Box flexDirection="column" borderStyle="round" borderColor={color('magenta')} backgroundColor="black" paddingX={1} width={width} height={CARD_HEIGHT} flexShrink={0}>
                <Box flexDirection="row" justifyContent="space-between" width={cardInner}><Text weight="bold">Settings</Text>{pageControls}</Box>
                {tabRow}
                {tabBody}
              </Box>
            </Box>
          ) : null}
        </Box>,
      )

    if (!enabled) {
      return frame(
        <Text dimColor wrap="truncate">
          {cl.phase === 'done' && files > 0
            ? `Changed: ${cl.changedFiles.map(f => f.split(/[\\/]/).pop()).join(', ')}`
            : 'Tool calls are showing. Open Settings to hide them again.'}
        </Text>,
      )
    }

    if (style === 'bars') {
      const live = cl.phase === 'working' || cl.phase === 'needs-you' || cl.phase === 'stuck' || cl.phase === 'stopped'
      const active = cl.tasks.find(t => t.status === 'active')
      const upcoming = cl.tasks.find(t => t.status === 'upcoming')
      let pillText = shortName(active ? active.name : 'Working', 32)
      let pillBg = 'magenta'
      if (cl.phase === 'needs-you') {
        pillText = 'Needs you'
        pillBg = 'yellow'
      } else if (cl.phase === 'stuck') {
        pillText = 'Stuck'
        pillBg = 'red'
      } else if (cl.phase === 'stopped') {
        pillText = 'Stopped'
        pillBg = 'gray'
      }
      // The words inside the bar: what Claude is doing now, else the step that comes next.
      const liveLabel = cl.phase === 'working' ? (cl.action !== '' ? `${cl.action}…` : upcoming ? upcoming.name : '') : ''
      type Item = {
        id: string
        name: string
        pillText: string
        bg: string
        pct: number
        isLive: boolean
        label: string
        onDismiss: () => void
      }
      const items: Item[] = finished.map(f => ({
        id: f.id,
        name: f.title,
        pillText: `✓ ${formatDuration(f.seconds * 1000)}`,
        bg: 'green',
        pct: 100,
        isLive: false,
        label: '',
        onDismiss: () => {
          void update($, finishedA, list => list.filter(x => x.id !== f.id))
        },
      }))
      if (live) {
        items.push({
          id: 'now',
          name: title0(cl),
          pillText,
          bg: pillBg,
          pct: Math.round(cl.bar ?? 0),
          isLive: cl.phase === 'working',
          label: liveLabel,
          onDismiss: () => {
            stopClock()
            void patch($, c => ({ ...newChecklist(), jobId: c.jobId }))
          },
        })
      }
      // Text takes at least 35% of the width (more if a name or stage needs it); the bar, percent and x take
      // everything that is left, so the row always runs to the right edge. The pill sits against the bar, and
      // every bar starts at the same column.
      // Every pill is the same width, so pills and bars line up on the left: short ones are padded with their own colour.
      const pillW = Math.min(34, Math.max(9, ...items.map(it => it.pillText.length + 2)))
      const maxPill = pillW
      const maxName = Math.max(12, ...items.map(it => it.name.length))
      const textBlock = Math.min(Math.floor(width * 0.6), Math.max(Math.floor(width * 0.35), 2 + maxName + 1 + maxPill))
      // Two cells of slack: if a terminal counts a symbol as wide, the bar gives way, never the name.
      const barW = Math.max(10, width - textBlock - (6 + 5) - 2)
      const rows: RenderChildren[] = items.map(it => (
        <Box key={`bar-${it.id}`} flexDirection="row">
          <Box width={textBlock - pillW} flexShrink={0} flexDirection="row">
            <Text color={color(it.bg)}>● </Text>
            <Text weight={(it.isLive) ? 'bold' : undefined} wrap="truncate">{shortName(it.name, Math.max(8, textBlock - 3 - pillW))}</Text>
          </Box>
          <Box flexShrink={0}>{pillOf(shortName(it.pillText, pillW - 2).padEnd(pillW - 2, ' '), it.bg)}</Box>
          {barSegments(it.pct, barW, tick, it.isLive && !isStill, it.label).map((seg, k) =>
            seg.kind === 'label' ? (
              <Text key={`seg-${k}`} weight="bold" inverse={isPlain} backgroundColor={isPlain ? undefined : it.bg} color={isPlain ? undefined : 'white'}>
                {seg.text}
              </Text>
            ) : seg.kind === 'fill' ? (
              <Text key={`seg-${k}`} color={color(it.bg)}>{seg.text}</Text>
            ) : (
              <Text key={`seg-${k}`} dimColor>{seg.text}</Text>
            ),
          )}
          <Text tabular>{` ${String(it.pct).padStart(3, ' ')}% `}</Text>
          <Button key={`x-${it.id}`} label="×" onPress={it.onDismiss} />
        </Box>
      ))
      const nextList =
        cl.phase === 'needs-you' && cl.question !== null ? (
          <Box flexDirection="column">
            <Text dimColor>next: {cl.question.question}</Text>
            {cl.question.options.map((o, i) => (
              <Button
                key={`choice${i + 1}`}
                hotkey={String(i + 1)}
                plain
                label={o}
                onPress={() => {
                  void patch($, c => ({ ...c, phase: 'working', needsYouReason: '', question: null, isBelled: false }))
                  void $.prompt.submit({ text: o, asUser: true })
                }}
              />
            ))}
            <Button
              key="dismiss-next"
              hotkey="0"
              plain
              label="dismiss"
              onPress={() => {
                void patch($, c => ({ ...c, phase: 'done', needsYouReason: '', question: null, isBelled: false }))
              }}
            />
          </Box>
        ) : null
      return frame(
        <Box flexDirection="column" width={width}>
          {rows.length === 0 ? <Text dimColor>Waiting for your next request.</Text> : null}
          {rows}
          {cl.phase === 'stuck' ? (
            <Text dimColor>{`⚠ ${cl.stuckReason}. Press Esc to stop, or type a message to steer.`}</Text>
          ) : null}
          {cl.phase === 'needs-you' && cl.question === null ? <Text dimColor>{`${cl.needsYouReason}  ↓ Answer below`}</Text> : null}
          {nextList}
        </Box>
      )
    }

    const title = title0(cl)
    const isSingle = cl.hasPlan && cl.tasks.length <= 1
    const isLive = cl.phase === 'working' || cl.phase === 'needs-you' || cl.phase === 'stuck' || cl.phase === 'stopped'
    const phasePill =
      cl.phase === 'needs-you'
        ? pillOf('Needs you', 'yellow')
        : cl.phase === 'stuck'
          ? pillOf('Stuck', 'red')
          : cl.phase === 'stopped'
            ? pillOf('Stopped', 'gray')
            : pillOf('Working', 'magenta')
    const stepNote = isSingle || cl.tasks.length === 0 ? '' : ` · Step ${stepNumber(cl)} of ${cl.tasks.length}`
    const detail =
      cl.phase === 'needs-you'
        ? `${cl.needsYouReason}  ↓ Answer below`
        : cl.phase === 'stuck'
          ? `${cl.stuckReason}. Press Esc to stop, or type a message to steer.`
          : cl.phase === 'stopped'
            ? 'You pressed Esc.'
            : cl.action !== ''
              ? `${cl.action}…`
              : ''
    const liveHead = isLive ? (
      <Box flexDirection="column">
        <Box flexDirection="row">
          {phasePill}
          <Text weight="bold" wrap="truncate">{` ${title}`}</Text>
          <Text dimColor tabular>{`${stepNote} · ${elapsed}`}</Text>
        </Box>
        {detail !== '' ? <Text dimColor wrap="truncate">{`  ${detail}`}</Text> : null}
      </Box>
    ) : null

    const showRows = isLive && !isSingle && cl.tasks.length > 0 && (cl.phase === 'working' || cl.phase === 'needs-you')
    const nameCol = Math.max(12, width - 24)
    const { doneCount, rows } = visibleRows(cl)
    const firstUpcoming = rows.findIndex(t => t.status === 'upcoming')
    const pct = (n: number) => `${String(Math.round(n)).padStart(3, ' ')}%`

    const rowEls = showRows
      ? rows.map((t, i) => {
          if (t.status === 'done') {
            return (
              <Box key={`r-${t.id}`} flexDirection="row">
                <Text color={color('success')}>✓ </Text>
                <Text dimColor>{fitName(t.name, nameCol)} </Text>
                <Text color={color('success')}>{meter(100)}</Text>
                <Text dimColor>  Done</Text>
              </Box>
            )
          }
          if (t.status === 'active') {
            const waiting = cl.phase === 'needs-you'
            return (
              <Box key={`r-${t.id}`} flexDirection="row">
                <Text weight="bold" color={color(waiting ? 'yellow' : 'magenta')}>{waiting ? '‖ ' : '▶ '}</Text>
                <Text weight="bold">{fitName(t.name, nameCol)} </Text>
                <Text color={color(waiting ? 'yellow' : 'magenta')}>{t.hasReported ? meter(t.shown) : sweep(tick, isStill || waiting)}</Text>
                <Text weight="bold" tabular>{t.hasReported ? `  ${pct(t.percent)}` : waiting ? '  Waiting' : '  Working'}</Text>
              </Box>
            )
          }
          return (
            <Box key={`r-${t.id}`} flexDirection="row">
              <Text dimColor>○ {fitName(t.name, nameCol)} </Text>
              <Text dimColor>{meter(0)}</Text>
              <Text dimColor>{i === firstUpcoming ? '  Next' : '  Up next'}</Text>
            </Box>
          )
        })
      : null

    const picker =
      cl.phase === 'needs-you' && cl.question !== null
        ? (
            <Box flexDirection="column">
              {cl.question.options.map((o, i) => (
                <Button
                  key={`choice${i + 1}`}
                  hotkey={String(i + 1)}
                  plain
                  label={o}
                  onPress={() => {
                    void patch($, c => ({ ...c, phase: 'working', needsYouReason: '', question: null, isBelled: false }))
                    void $.prompt.submit({ text: o, asUser: true })
                  }}
                />
              ))}
              <Text dimColor>…or type your own answer below</Text>
            </Box>
          )
        : null

    // Finished jobs keep themselves, as in the bar view: the last three stay as one calm row each, with a × to clear
    // one. The newest also shows its steps ticked.
    const lastId = finished.length > 0 ? finished[finished.length - 1]!.id : ''
    const historyEls = finished.map(f => {
      const isJustDone = cl.phase === 'done' && f.id === `j${cl.jobId}`
      const changed = isJustDone && files > 0 ? ` · changed ${files} ${files === 1 ? 'file' : 'files'}` : ''
      return (
        <Box key={`old-${f.id}`} flexDirection="column">
          <Box flexDirection="row" justifyContent="space-between" width={width}>
            <Text wrap="truncate">
              <Text weight="bold" color={color('success')}>{'✓ '}</Text>
              <Text>{f.title}</Text>
              <Text dimColor tabular>{` · took ${formatDuration(f.seconds * 1000)}${changed}`}</Text>
            </Text>
            <Button
              key={`x-${f.id}`}
              label="×"
              onPress={() => {
                void update($, finishedA, list => list.filter(x => x.id !== f.id))
              }}
            />
          </Box>
          {f.id === lastId && stepsOf(f).length > 1
            ? stepsOf(f).map((n, i) => <Text key={`${f.id}-${i}`} dimColor>{`  ✓ ${n}`}</Text>)
            : null}
        </Box>
      )
    })
    return frame(
      <Box flexDirection="column" width={width}>
        {historyEls}
        {liveHead}
        {picker}
        {showRows && doneCount > 0 ? <Text dimColor color={color('success')}>{`✓ ${doneCount} steps done`}</Text> : null}
        {rowEls}
        {!isLive && finished.length === 0 ? <Text dimColor>Waiting for your next request.</Text> : null}
      </Box>
    )
    } catch (err) {
      // Never let the band vanish silently: say what went wrong, and how to carry on.
      const why = err instanceof Error ? err.message : String(err)
      return stack(
        <Box flexDirection="column">
          <Text color="red" wrap="truncate">{`Session Panel hit a problem: ${why.slice(0, 80)}`}</Text>
          <Text dimColor>Type /simple off to hide Session Panel, or /simple bars or /simple list to try the other look.</Text>
        </Box>,
      )
    }
  })
}

